}

export function getNodeTags(node: GraphNode): string[] {
  const raw = node.attributes.tags;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return [];
  return Object.entries(raw as Record<string, unknown>)
    .filter(([k]) => k !== "Name")
    .map(([k, v]) => `${k}:${String(v)}`);
}

