/**
 * Send a base64-encoded zip archive to the Terraform worker, which runs
 * `terraform init + plan + show -json`, then parses the resulting plan into
 * a GraphModel via the parser service.
 */
export async function runPlan(
  archiveBase64: string,
  vars?: string[],
): Promise<ApiResult<GraphModel>> {
  let planJson: unknown;
  try {
    const workerRes = await fetchWithTimeout(`${WORKER_URL}/run`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ archiveBase64, vars }),
    });

    const workerBody: unknown = await workerRes.json();

    if (!workerRes.ok) {
      const errBody = workerBody as Record<string, unknown>;
      return {
        success: false,
        error: typeof errBody["error"] === "string" ? errBody["error"] : `Worker error ${workerRes.status}`,
      };
    }

    planJson = (workerBody as Record<string, unknown>)["plan"];
    if (!planJson) {
      return { success: false, error: "Worker returned no plan JSON" };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : "Worker connection failed";
    return { success: false, error: message };
  }

  return parsePlan(planJson);
}

/**
 * tauri-bridge.ts
 *
 * Thin adapter so the React UI can call Tauri IPC commands
 * instead of /api/* HTTP routes — with web fallback built in.
 *
 * Usage:
 *   import { parsePlan, openPlanFile, isTauri } from "@/lib/tauri-bridge";
 */

// Detect if running inside Tauri desktop or in a regular browser
export function isTauri(): boolean {
  return typeof window !== "undefined" && "__TAURI_INTERNALS__" in window;
}

async function tauriInvoke<T>(
  cmd: string,
  args?: Record<string, unknown>
): Promise<T> {
  const { invoke } = await import("@tauri-apps/api/core");
  return invoke<T>(cmd, args);
}

// ── Parse Plan ────────────────────────────────────────────────────────────────

export async function parsePlan(raw: string): Promise<unknown> {
  if (isTauri()) {
    // Tauri backend expects JSON string — Rust side parses it
    return tauriInvoke("parse_plan", { raw });
  }
  // Web fallback — existing Next.js API route
  const parsed: unknown = JSON.parse(raw);
  const res = await fetch("/api/parse", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(parsed),
  });
  if (!res.ok) {
    const err = (await res.json().catch(() => ({}))) as Record<string, unknown>;
    throw new Error(typeof err["error"] === "string" ? err["error"] : "Parse failed");
  }
  return res.json();
}

