      resetAll: () => set({ overrides: {} }),

      getNodeOverrides: (nodeId) => get().overrides[nodeId],

      customizedCount: () =>
        Object.values(get().overrides).filter((o) => Object.keys(o).length > 0).length,
    }),
    {
      name: "terraform-viz:usage-overrides",
    }
  )
);

