function detectProvider(resourceType: string): CloudProvider {
  if (resourceType.startsWith("aws_")) return CloudProvider.AWS;
  if (resourceType.startsWith("azurerm_")) return CloudProvider.AZURE;
  if (resourceType.startsWith("google_")) return CloudProvider.GCP;
  return CloudProvider.UNKNOWN;
}

export function classifyResource(resourceType: string): ResourceClassification {
  const provider = detectProvider(resourceType);

  const layerByProvider: Record<CloudProvider, (type: string) => ResourceLayer> = {
    [CloudProvider.AWS]: classifyAwsLayer,
    [CloudProvider.AZURE]: classifyAzureLayer,
    [CloudProvider.GCP]: classifyGcpLayer,
    [CloudProvider.UNKNOWN]: () => ResourceLayer.UNKNOWN,
  };

  const classify = layerByProvider[provider] ?? ((_type: string): ResourceLayer => ResourceLayer.UNKNOWN);
  const layer = classify(resourceType);
  return { provider, layer };
}

import { randomUUID } from "node:crypto";
import { ChangeAction, type GraphEdge, type GraphModel, type GraphNode } from "@terraform-viz/graph-schema";
import { classifyResource } from "./layer-classifier.js";
import type {
  TerraformModule,
  TerraformPlan,
  TerraformResource,
  TerraformResourceChange,
} from "./terraform-plan.types.js";

function flattenResources(
  module: TerraformModule,
  moduleAddress: string | null,
): { resource: TerraformResource; moduleAddress: string | null }[] {
  const result: { resource: TerraformResource; moduleAddress: string | null }[] = [];

  for (const resource of module.resources ?? []) {
    result.push({ resource, moduleAddress });
  }

  for (const child of module.child_modules ?? []) {
    result.push(...flattenResources(child, child.address));
  }

  return result;
}

function resolveChangeAction(
  address: string,
  changes: readonly TerraformResourceChange[],
): ChangeAction {
  const change = changes.find((c) => c.address === address);
  if (!change) return ChangeAction.NO_OP;

  const { actions } = change.change;
  if (actions.includes("create") && actions.includes("delete")) return ChangeAction.REPLACE;
  if (actions.includes("create")) return ChangeAction.CREATE;
  if (actions.includes("delete")) return ChangeAction.DELETE;
  if (actions.includes("update")) return ChangeAction.UPDATE;
  return ChangeAction.NO_OP;
}

function buildNode(
  resource: TerraformResource,
  changeAction: ChangeAction,
  moduleAddress: string | null,
): GraphNode {
  const { provider, layer } = classifyResource(resource.type);
  return {
    id: resource.address,
    address: resource.address,
    type: resource.type,
    name: resource.name,
    provider,
    layer,
    attributes: resource.values,
    changeAction,
    moduleAddress,
  };
}

function buildEdges(
  entries: { resource: TerraformResource; moduleAddress: string | null }[],
): GraphEdge[] {
  return entries.flatMap(({ resource }) =>
    (resource.depends_on ?? []).map((dep

}

function buildEdges(
  entries: { resource: TerraformResource; moduleAddress: string | null }[],
): GraphEdge[] {
  return entries.flatMap(({ resource }) =>
    (resource.depends_on ?? []).map((dep) => ({
      source: dep,
      target: resource.address,
    })),
  );
}

function getRootModule(plan: TerraformPlan): TerraformModule {
  const root = plan.planned_values?.root_module ?? plan.values?.root_module;
  if (!root) throw new Error("No root module found in Terraform plan JSON");
  return root;
}

export function buildGraphModel(plan: TerraformPlan): GraphModel {
  const rootModule = getRootModule(plan);
  const entries = flattenResources(rootModule, null);
  const resourceChanges = plan.resource_changes ?? [];

  const nodes = entries.map(({ resource, moduleAddress }) =>
    buildNode(resource, resolveChangeAction(resource.address, resourceChanges), moduleAddress),
  );

  const edges = buildEdges(entries).filter((edge) =>
    nodes.some((node) => node.id === edge.source),
  );

  return {
    id: randomUUID(),
    nodes,
    edges,
    terraformVersion: plan.terraform_version,
    createdAt: new Date().toISOString(),
  };
}

export interface TerraformResource {
  readonly address: string;
  readonly mode: string;
  readonly type: string;
  readonly name: string;
  readonly provider_name: string;
  readonly schema_version: number;
  readonly values: Record<string, unknown>;
  readonly depends_on?: readonly string[];
}

export interface TerraformModule {
  readonly resources?: readonly TerraformResource[];
  readonly child_modules?: readonly TerraformChildModule[];
}

export interface TerraformChildModule extends TerraformModule {
  readonly address: string;
}

export interface TerraformResourceChange {
  readonly address: string;
  readonly module_address?: string | null;
  readonly mode: string;
  readonly type: string;
  readonly name: string;
  readonly provider_name: string;
  readonly change: {
    readonly actions: readonly string[];
    readonly before: Record<string, unknown> | null;
    readonly after: Record<string, unknown> | null;
  };
}

export interface TerraformPlan {
  readonly format_version: string;
  readonly terraform_version: string;
  readonly planned_values?: {
    readonly root_module: TerraformModule;
  };
  readonly values?: {
    readonly root_module: TerraformModule;
  };
  readonly resource_changes?: readonly TerraformResourceChange[];
}

import { Router, type Request, type Response } from "express";
import { z } from "zod";
import { parsePlanUseCase } from "../../application/parse-plan.use-case.js";

export const parserRouter = Router();

const parseSchema = z.record(z.string(), z.unknown());

parserRouter.post("/parse", (request: Request, response: Response): void => {
  const parsed = parseSchema.safeParse(request.body);
  if (!parsed.success) {
    response.status(400).json({ error: "Validation failed", details: parsed.error });
    return;
  }
  const result = parsePlanUseCase(parsed.data);

  if (result.success) {
    response.status(200).json(result.data);
    return;
  }

  response.status(400).json({ error: result.error });
});

parserRouter.get("/health", (_request: Request, response: Response): void => {
  response.status(200).json({ status: "ok", service: "parser" });
});

