): GraphNode {
  return {
    id: `n-${type}`,
    address: `aws_resource.${type}`,
    type,
    name: type,
    provider,
    layer: ResourceLayer.COMPUTE,
    changeAction: ChangeAction.NO_OP,
    attributes: attributes,
    moduleAddress: null,
  };
}

